'use strict';

var index = require('./index-KWxdc1K1.cjs');
require('quansync');

async function getToJsonSchemaFn() {
  try {
    const effect = await import('effect');
    if ("JSONSchema" in effect) {
      const { JSONSchema } = effect;
      return (schema, options) => {
        const io = index.ioOf(options);
        const side = schema;
        if (io === "input") {
          const definitions = {};
          const jsonSchema = JSONSchema.fromAST(side.ast, { definitions });
          return {
            $schema: "http://json-schema.org/draft-07/schema#",
            ...jsonSchema,
            ...Object.keys(definitions).length > 0 && { $defs: definitions }
          };
        }
        return JSONSchema.make(
          io === "output" ? effect.Schema.typeSchema(side) : side
        );
      };
    }
    const { JsonSchema, Schema } = effect;
    return (schema, options) => {
      const { definitions, schema: jsonSchema } = JsonSchema.toDocumentDraft07(
        Schema.toJsonSchemaDocument(
          index.ioOf(options) === "output" ? Schema.toType(schema) : schema
        )
      );
      return {
        $schema: JsonSchema.META_SCHEMA_URI_DRAFT_07,
        ...jsonSchema,
        ...Object.keys(definitions).length > 0 && { definitions }
      };
    };
  } catch {
    throw new index.MissingDependencyError("effect");
  }
}

exports.default = getToJsonSchemaFn;
